import{_ as r,a0 as i,w as p,s as b,ao as s,I as o,x as l,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器 | LCTT x X-CMD","titleTemplate":false,"description":"shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator","title":"shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器","tag":"201508","desc":""},"relativePath":"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator.md","filePath":"[post].md"}'),d={name:"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator.md"};function h(x,e,u,m,A,E){const n=i("Link");return p(),b("div",null,[e[25]||(e[25]=s('<h1 id="shellinabox-一款使用-ajax-的基於-web-的終端模擬器" tabindex="-1">shellinabox：一款使用 AJAX 的基於 Web 的終端模擬器 <a class="header-anchor" href="#shellinabox-一款使用-ajax-的基於-web-的終端模擬器" aria-label="Permalink to “shellinabox：一款使用  AJAX 的基於 Web 的終端模擬器”">​</a></h1><h3 id="shellinabox簡介" tabindex="-1">shellinabox簡介 <a class="header-anchor" href="#shellinabox簡介" aria-label="Permalink to “shellinabox簡介”">​</a></h3><p>通常情況下，我們在訪問任何遠程服務器時，會使用常見的通信工具如OpenSSH和Putty等。但是，有可能我們在防火牆後面不能使用這些工具訪問遠程系統，或者防火牆只允許HTTPS流量才能通過。不用擔心！即使你在這樣的防火牆後面，我們依然有辦法來訪問你的遠程系統。而且，你不需要安裝任何類似於OpenSSH或Putty的通訊工具。你只需要有一個支持JavaScript和CSS的現代瀏覽器，並且你不用安裝任何插件或第三方應用軟件。</p><p>這個 <strong>Shell In A Box</strong>，發音是<strong>shellinabox</strong>，是由<strong>Markus Gutschke</strong>開發的一款自由開源的基於Web的Ajax的終端模擬器。它使用AJAX技術，通過Web瀏覽器提供了類似原生的 Shell 的外觀和感受。</p>',4)),o("p",null,[e[1]||(e[1]=l("這個",-1)),e[2]||(e[2]=o("strong",null,"shellinaboxd",-1)),e[3]||(e[3]=l("守護進程實現了一個Web服務器，能夠偵聽指定的端口。其Web服務器可以發佈一個或多個服務，這些服務顯示在用 AJAX Web 應用實現的VT100模擬器中。默認情況下，端口為4200。你可以更改默認端口到任意選擇的任意端口號。在你的遠程服務器安裝shellinabox以後，如果你想從本地系統接入，打開Web瀏覽器並導航到：**",-1)),t(n,{href:"http://IP-Address:4200/**%E3%80%82%E8%BC%B8%E5%85%A5%E4%BD%A0%E7%9A%84%E7%94%A8%E6%88%B7%E5%90%8D%E5%92%8C%E5%AF%86%E7%A2%BC%EF%BC%8C%E7%84%B6%E5%BE%8C%E5%B0%B1%E5%8F%AF%E4%BB%A5%E9%96%8B%E5%A7%8B%E4%BD%BF%E7%94%A8%E4%BD%A0%E9%81%A0%E7%A8%8B%E7%B3%BB%E7%B5%B1%E7%9A%84Shell%E3%80%82%E7%9C%8B%E8%B5%B7%E4%BE%86%E5%BE%88%E6%9C%89%E8%B6%A3%EF%BC%8C%E4%B8%8D%E6%98%AF%E5%97%8E%EF%BC%9F%E7%A2%BA%E5%AF%A6"},{default:a(()=>[...e[0]||(e[0]=[l("http://IP-Address:4200/**。輸入你的用户名和密碼，然後就可以開始使用你遠程系統的Shell。看起來很有趣，不是嗎？確實",-1)])]),_:1}),e[4]||(e[4]=l(" 有趣！",-1))]),e[26]||(e[26]=s(`<p><strong>免責聲明</strong>:</p><p>shellinabox不是SSH客户端或任何安全軟件。它僅僅是一個應用程序，能夠通過Web瀏覽器模擬一個遠程系統的Shell。同時，它和SSH沒有任何關係。這不是可靠的安全地遠程控制您的系統的方式。這只是迄今為止最簡單的方法之一。無論如何，你都不應該在任何公共網絡上運行它。</p><h3 id="安裝shellinabox" tabindex="-1">安裝shellinabox <a class="header-anchor" href="#安裝shellinabox" aria-label="Permalink to “安裝shellinabox”">​</a></h3><h4 id="在debian-ubuntu系統上" tabindex="-1">在Debian / Ubuntu系統上： <a class="header-anchor" href="#在debian-ubuntu系統上" aria-label="Permalink to “在Debian / Ubuntu系統上：”">​</a></h4><p>shellinabox在默認庫是可用的。所以，你可以使用命令來安裝它：</p><pre><code>$ sudo apt-get install shellinabox
</code></pre><h4 id="在rhel-centos系統上" tabindex="-1">在RHEL / CentOS系統上： <a class="header-anchor" href="#在rhel-centos系統上" aria-label="Permalink to “在RHEL / CentOS系統上：”">​</a></h4><p>首先，使用命令安裝EPEL倉庫：</p><pre><code># yum install epel-release
</code></pre><p>然後，使用命令安裝shellinabox：</p><pre><code># yum install shellinabox
</code></pre><p>完成！</p><h3 id="配置shellinabox" tabindex="-1">配置shellinabox <a class="header-anchor" href="#配置shellinabox" aria-label="Permalink to “配置shellinabox”">​</a></h3><p>正如我之前提到的，shellinabox偵聽端口默認為<strong>4200</strong>。你可以將此端口更改為任意數字，以防別人猜到。</p><p>在Debian/Ubuntu系統上shellinabox配置文件的默認位置是<strong>/etc/default/shellinabox</strong>。在RHEL/CentOS/Fedora上，默認位置在<strong>/etc/sysconfig/shellinaboxd</strong>。</p><p>如果要更改默認端口，</p><p>在Debian / Ubuntu：</p><pre><code>$ sudo vi /etc/default/shellinabox
</code></pre><p>在RHEL / CentOS / Fedora：</p><pre><code># vi /etc/sysconfig/shellinaboxd
</code></pre><p>更改你的端口到任意數字。因為我在本地網絡上測試它，所以我使用默認值。</p><pre><code># Shell in a box daemon configuration
# For details see shellinaboxd man page

# Basic options
USER=shellinabox
GROUP=shellinabox
CERTDIR=/var/lib/shellinabox
PORT=4200
OPTS=&quot;--disable-ssl-menu -s /:LOGIN&quot;

# Additional examples with custom options:

# Fancy configuration with right-click menu choice for black-on-white:
# OPTS=&quot;--user-css Normal:+black-on-white.css,Reverse:-white-on-black.css --disable-ssl-menu -s /:LOGIN&quot;

# Simple configuration for running it as an SSH console with SSL disabled:
# OPTS=&quot;-t -s /:SSH:host.example.com&quot;
</code></pre><p>重啓shelinabox服務。</p><p><strong>在Debian/Ubuntu:</strong></p><pre><code>$ sudo systemctl restart shellinabox
</code></pre><p>或者</p><pre><code>$ sudo service shellinabox restart
</code></pre><p>在RHEL/CentOS系統，運行下面的命令能在每次重啓時自動啓動shellinaboxd服務</p><pre><code># systemctl enable shellinaboxd
</code></pre><p>或者</p><pre><code># chkconfig shellinaboxd on
</code></pre><p>如果你正在運行一個防火牆，記得要打開端口<strong>4200</strong>或任何你指定的端口。</p><p>例如，在RHEL/CentOS系統，你可以如下圖所示允許端口。</p><pre><code># firewall-cmd --permanent --add-port=4200/tcp
</code></pre><hr><pre><code># firewall-cmd --reload
</code></pre><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3>`,37)),o("p",null,[e[6]||(e[6]=l("現在，在你的客户端系統，打開Web瀏覽器並導航到：",-1)),o("strong",null,[t(n,{href:"https://ip-address-of-remote-servers:4200"},{default:a(()=>[...e[5]||(e[5]=[l("https://ip-address-of-remote-servers:4200",-1)])]),_:1})]),e[7]||(e[7]=l("。",-1))]),e[27]||(e[27]=s(`<p><strong>注意</strong>：如果你改變了端口，請填寫修改後的端口。</p><p>你會得到一個證書問題的警告信息。接受該證書並繼續。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/Privacy-error-Google-Chrome_001.jpg" alt="Privacy error - Google Chrome_001"></p><p>輸入遠程系統的用户名和密碼。現在，您就能夠從瀏覽器本身訪問遠程系統的外殼。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_003.jpg" alt="Shell In A Box - Google Chrome_003"></p><p>右鍵點擊你瀏覽器的空白位置。你可以得到一些有很有用的額外菜單選項。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_004.jpg" alt="Shell In A Box - Google Chrome_004"></p><p>從現在開始，你可以通過本地系統的Web瀏覽器在你的遠程服務器隨意操作。</p><p>當你完成工作時，記得輸入<code>exit</code>退出。</p><p>當再次連接到遠程系統時，單擊<strong>連接</strong>按鈕，然後輸入遠程服務器的用户名和密碼。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_005.jpg" alt="Shell In A Box - Google Chrome_005"></p><p>如果想了解shellinabox更多細節，在你的終端鍵入下面的命令：</p><pre><code># man shellinabox
</code></pre><p>或者</p><pre><code># shellinaboxd -help
</code></pre>`,15)),o("p",null,[e[9]||(e[9]=l("同時，參考",-1)),t(n,{href:"https://code.google.com/p/shellinabox/wiki/shellinaboxd_man"},{default:a(()=>[...e[8]||(e[8]=[l("shellinabox 在wiki頁面的介紹",-1)])]),_:1}),e[10]||(e[10]=l("，來了解shellinabox的綜合使用細節。",-1))]),e[28]||(e[28]=o("h3",{id:"結論",tabindex:"-1"},[l("結論 "),o("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),e[29]||(e[29]=o("p",null,"正如我之前提到的，如果你在服務器運行在防火牆後面，那麼基於web的SSH工具是非常有用的。有許多基於web的SSH工具，但shellinabox是非常簡單而有用的工具，可以從的網絡上的任何地方，模擬一個遠程系統的Shell。因為它是基於瀏覽器的，所以你可以從任何設備訪問您的遠程服務器，只要你有一個支持JavaScript和CSS的瀏覽器。",-1)),e[30]||(e[30]=o("p",null,"就這些啦。祝你今天有個好心情！",-1)),e[31]||(e[31]=o("h4",{id:"參考鏈接",tabindex:"-1"},[l("參考鏈接： "),o("a",{class:"header-anchor",href:"#參考鏈接","aria-label":"Permalink to “參考鏈接：”"},"​")],-1)),o("ul",null,[o("li",null,[t(n,{href:"https://code.google.com/p/shellinabox/"},{default:a(()=>[...e[11]||(e[11]=[l("shellinabox website",-1)])]),_:1})])]),e[32]||(e[32]=o("hr",null,null,-1)),o("p",null,[e[13]||(e[13]=l("via: ",-1)),t(n,{href:"http://www.unixmen.com/shellinabox-a-web-based-ajax-terminal-emulator/"},{default:a(()=>[...e[12]||(e[12]=[l("http://www.unixmen.com/shellinabox-a-web-based-ajax-terminal-emulator/",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=l("作者：",-1)),t(n,{href:"http://www.unixmen.com/author/sk/"},{default:a(()=>[...e[14]||(e[14]=[l("SK",-1)])]),_:1}),e[18]||(e[18]=l(" 譯者：",-1)),t(n,{href:"https://github.com/xiaoyu33"},{default:a(()=>[...e[15]||(e[15]=[l("xiaoyu33",-1)])]),_:1}),e[19]||(e[19]=l(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[16]||(e[16]=[l("wxy",-1)])]),_:1})]),o("p",null,[e[22]||(e[22]=l("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[20]||(e[20]=[l("LCTT",-1)])]),_:1}),e[23]||(e[23]=l(" 原創翻譯，",-1)),t(n,{href:"http://linux.cn/"},{default:a(()=>[...e[21]||(e[21]=[l("Linux中國",-1)])]),_:1}),e[24]||(e[24]=l(" 榮譽推出",-1))])])}const C=r(d,[["render",h]]);export{f as __pageData,C as default};
